type Step = { id: string; prompt: string; expectedConcept: string }

type LearnerState = { stepIndex: number; mastery: Record<string, number> }

export function advance(state: LearnerState, concept: string): LearnerState {
  const current = state.mastery[concept] ?? 0
  return {
    ...state,
    stepIndex: state.stepIndex + 1,
    mastery: { ...state.mastery, [concept]: Math.min(1, current + 0.1) }
  }
}

export function hintLevel(attempts: number, stalledSeconds: number): number {
  if (attempts > 4 || stalledSeconds > 90) return 3
  if (attempts > 2 || stalledSeconds > 45) return 2
  if (attempts > 1 || stalledSeconds > 20) return 1
  return 0
}
